// ============================================================================
// U1 (план docs/plans/2026-08-10-001-...): проброс found_info в личный кабинет.
//
// ВНИМАНИЕ: боевой воркфлоу в n8n этой правки НЕ содержит. Выкат в прод вне
// скоупа плана, проверка идёт на форке [TEST] TOOL: AUTO.RU EVALUATION.
// Не импортировать этот файл в боевой n8n до отдельного согласования —
// см. docs/test-contour-checklist.md.
//
// Кабинет ждёт found_info "как отдал сервис" плюс добавленный ключ plate:
// ключи не переименовывать, поля не фильтровать, URL фото не нормализовать
// (photos.main приходит протокол-относительным, бот дополняет сам).
// Плоские tradein_* ниже — контракт CRM и комбо-ветки, их не трогать.
// ============================================================================

// Функция для красивого округления до 10 000 руб
function round10k(val) {
    if (!val) return 0;
    return Math.round(Number(val) / 10000) * 10000;
}

let result = {};
let inputData = $input.item.json;

// 🛑 ПЕРЕХВАТ ОШИБКИ ФОРМАТА (если сработала ветка false в If2)
// План 2026-09-08-001, U7: причина отказа приходит из ноды валидации отдельным
// полем reason. Наружу уходит не один статус, а три — блоки ST_*_TOOL_NEEDED_V2
// различают «не хватает кода региона» и «это не похоже на номер» и задают
// клиенту разный вопрос вместо одной и той же фразы дважды подряд.
// plate_seen — уже разобранная часть номера: она даёт модели материал для
// конкретной формулировки («вижу Т582ХР, допишите код региона»).
if (inputData.is_valid === false) {
    var reason = inputData.reason || "NOT_A_PLATE";
    if (reason === "NO_REGION") {
        return {
            status: "NO_REGION",
            plate_seen: inputData.plate,
            message: "Госномер разобран, но в нём нет кода региона. Назови клиенту то, что уже видно, и попроси дописать код региона."
        };
    }
    if (reason === "BAD_REGION") {
        return {
            status: "INVALID_DATA",
            plate_seen: inputData.plate,
            message: "В госномере указан несуществующий код региона. Попроси клиента проверить код региона и написать номер целиком."
        };
    }
    return {
        status: "INVALID_DATA",
        message: "Системная ошибка: Неверный формат госномера. Деликатно попроси его написать полный госномер."
    };
}

// --- U1: сборка found_info -------------------------------------------------
function safeNodeJson(nodeName) {
    try { return $(nodeName).first().json || {}; } catch (e) { return {}; }
}

// Госномера в ответе auto.ru нет — он приходит на вход. Берём нормализованный
// (верхний регистр, без пробелов и тире) из ноды валидации, фолбэк — сырой вход.
function resolvePlate() {
    const cleaned = safeNodeJson('Code in JavaScript1').plate;
    if (cleaned) return String(cleaned);
    const raw = safeNodeJson('Execute Workflow Trigger').plate;
    return raw ? String(raw) : "";
}

// Пустой found_info ключа не создаёт: кабинет трактует отсутствие как
// "оценки не было" и показывает редактируемые поля — это штатное поведение.
function buildFoundInfo(src) {
    if (!src || typeof src !== 'object' || Array.isArray(src)) return null;
    if (!Object.keys(src).length) return null;
    const plate = resolvePlate();
    return plate ? Object.assign({}, src, { plate: plate }) : Object.assign({}, src);
}

// 💥 НОВОЕ: Извлекаем детальные характеристики авто, если Авто.ру их нашел
let carDetails = {};
if (inputData.found_info) {
    carDetails = {
        tradein_make: inputData.found_info.mark || "",
        tradein_model: inputData.found_info.model || "",
        tradein_year: inputData.found_info.year || 0,
        tradein_horse_power: inputData.found_info.horse_power || 0,
        tradein_transmission: inputData.found_info.transmission || "",
        tradein_steering_wheel: inputData.found_info.steering_wheel || ""
    };
}

if (inputData.prices && inputData.prices.tradein) {
    // Успех от второго запроса (оценка по параметрам)
    result = {
        status: "SUCCESS",
        car_info: "Оценка по техническим параметрам",
        tradein_price_from: round10k(inputData.prices.tradein.from),
        tradein_price_to: round10k(inputData.prices.tradein.to),
        market_price_from: round10k(inputData.prices.autoru.from),
        market_price_to: round10k(inputData.prices.autoru.to),
        ...carDetails // Вклеиваем детали для CRM
    };
} else if (inputData.price_range && inputData.price_range.from > 0) {
    // Успех от первого запроса
    result = {
        status: "SUCCESS",
        car_info: `${inputData.found_info.mark} ${inputData.found_info.model} (${inputData.found_info.year} г.)`,
        tradein_price_from: round10k(inputData.price_range.from),
        tradein_price_to: round10k(inputData.price_range.to),
        ...carDetails // Вклеиваем детали для CRM
    };
} else if (inputData.error === "IN_PROGRESS") {
    // Авто.ру ушел собирать данные
    result = {
        status: "IN_PROGRESS",
        message: "Отчет по этому авто сейчас формируется, базы отвечают долго. Извинись перед клиентом за задержку и, чтобы не заставлять его ждать, сразу предложи приехать в салон для точной живой оценки или предложи звонок от специалиста."
    };
} else {
    // Машина вообще не найдена
    result = {
        status: "NOT_FOUND",
        message: "Автомобиль не найден в базах. Сообщи об этом клиенту и сразу предложи приехать в салон для точной живой оценки или предложи звонок от специалиста."
    };
}

// --- U1: found_info уезжает только при реальной оценке ---------------------
// Ветки IN_PROGRESS / NOT_FOUND / INVALID_DATA остаются без ключа (контракт R5).
if (result.status === "SUCCESS") {
    const foundInfo = buildFoundInfo(inputData.found_info);
    if (foundInfo) result.found_info = foundInfo;
}

return result;

