// Забираем номер из входящих данных
let rawPlate = $input.item.json.plate || "";

// 1. Очищаем номер: разделители убираем, приводим к верхнему регистру.
// Точка и запятая добавлены к пробелу и тире — клиенты пишут «Р491.НК,37».
let cleanPlate = String(rawPlate).replace(/[\s\-.,]/g, '').toUpperCase();

// 2. VIN распознаётся ДО любых преобразований и наружу уходит как есть.
// Поле auto.ru называется vin_or_lp и принимает оба идентификатора, а VIN
// пишется ТОЛЬКО латиницей — конвертация гомоглифов (шаг 4) его уничтожила бы.
// Проверка стоит здесь, а не после отрезания хвоста: VIN, оканчивающийся на
// RU, иначе потерял бы два знака и перестал бы распознаваться.
// VIN как вход оценки сегодня не поддержан — в конвейере его нет нигде
// (ни в описании evaluate_auto, ни в блоках NocoDB, ни в боте). Узел обязан
// лишь не портить строку. План 2026-09-08-001, U9.
const VIN_RE = /^[A-HJ-NPR-Z0-9]{17}$/;
if (VIN_RE.test(cleanPlate)) {
  return { plate: cleanPlate, is_valid: false, reason: "VIN_UNSUPPORTED",
           mileage: $input.item.json.mileage };
}

// 3. Хвост региона «RUS» / «РУС» / «RU» — только с конца строки.
// Якорь обязателен: без него 'RU' вырезалось бы из середины и, например,
// Х318ТЕ750 потерял бы букву. Инцидент: исполнения #3932 и #3937,
// «Т582ХР 33 rus» отвергался валидацией, клиент потерян по таймауту.
cleanPlate = cleanPlate.replace(/(RUS|РУС|RU)$/, '');

// 4. Гомоглифы: латинская запись номера приводится к кириллической.
// РАБОЧЕЕ ДОПУЩЕНИЕ (решение владельца 2026-09-08), не подтверждённый факт:
// auto.ru ищет по кириллической записи. Явного правила про алфавит поля
// vin_or_lp в документации сервиса нет; в примере запроса госномер записан
// кириллицей (В853КС77). Допущение опровергается появлением латинского
// номера, который сервис нашёл бы как есть, — тогда шаг снимается.
const LAT2CYR = { A: 'А', B: 'В', E: 'Е', K: 'К', M: 'М', H: 'Н',
                  O: 'О', P: 'Р', C: 'С', T: 'Т', Y: 'У', X: 'Х' };
cleanPlate = cleanPlate.replace(/[ABEKMHOPCTYX]/g, function (c) { return LAT2CYR[c]; });

// 5. Разбор по группам вместо цельного анкер-регэкспа: так «нет региона»
// отличается от «регион неверный», и блоки ST_*_TOOL_NEEDED_V2 могут задать
// клиенту конкретный вопрос вместо общего «номер кажется неполным» дважды.
const PLATE_RE = /^([АВЕКМНОРСТУХ])(\d{3})([АВЕКМНОРСТУХ]{2})(\d{2,3})?$/;
const m = PLATE_RE.exec(cleanPlate);

let isValid = false;
let reason = "NOT_A_PLATE";
if (m) {
  const region = m[4];
  if (!region) {
    reason = "NO_REGION";
  } else if (region.length === 2) {
    // двузначные коды: 01..99, кода «00» не существует
    isValid = Number(region) >= 1;
    reason = isValid ? "OK" : "BAD_REGION";
  } else {
    // трёхзначные коды РФ начинаются только на 1, 7 или 9 (102, 750, 977…).
    // Правило, а не перечень: переживает появление новых кодов. Оно же ловит
    // склейку номера с числом — исполнение #3974, «К647МУ211» проходил
    // валидацию и возвращался из auto.ru немым NOT_FOUND.
    isValid = region[0] === '1' || region[0] === '7' || region[0] === '9';
    reason = isValid ? "OK" : "BAD_REGION";
  }
}

// 6. Формируем результат
return {
  plate: cleanPlate, // Отдаем очищенный номер дальше
  is_valid: isValid,
  reason: reason,    // OK | NO_REGION | BAD_REGION | NOT_A_PLATE | VIN_UNSUPPORTED
  mileage: $input.item.json.mileage // Пробрасываем пробег дальше
};
